const historyReviewByTopic = new Map(historyReviewModules.map(module=>[module.key,module]));
const historySubject = subjects.find(subject=>subject.id==='history');
for (const module of historyReviewModules) {
  historySubject.topics.push({
    key:module.key,
    title:module.title,
    term:'上',
    description:module.description,
    questions:module.questions.map(question=>({...question, subject:historySubject.id, topic:module.key}))
  });
}
